//! shadcn-svelte components, as generated by its CLI, running in the host.
//! `examples/shadcn` uses the ones that work; this drives that page.
//!
//! Build the bundle first: `pnpm run build` in the repository root.

use std::path::Path;

use svelte_blitz_host::SvelteDocument;
use svelte_blitz_host::app::App;

#[test]
fn shadcn_components_render_and_react() {
    let dist = Path::new(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../examples/shadcn/dist"
    ));
    let app = App::from_dir(dist).expect("run `pnpm run build` in the repository root first");
    let mut doc = SvelteDocument::for_app(&app).unwrap();
    doc.layout(900, 700);
    let text = |doc: &SvelteDocument, selector: &str| doc.text(doc.query(selector).unwrap());

    // Every shadcn component has `bind:this={ref}` on its root element, which
    // Svelte refuses for a custom renderer. The preset rewrites it; the page
    // binds a Button's ref and reports whether a node arrived.
    assert_eq!(text(&doc, "#ref"), "ref bound");

    // The components carry shadcn's classes and data attributes, and its theme applies.
    let button = doc.query("#count").unwrap();
    assert_eq!(doc.attr(button, "data-slot").as_deref(), Some("button"));
    let (_, _, width, height) = doc.rect(button).unwrap();
    assert!(
        width > 60.0 && height >= 28.0,
        "the button is styled: {width}x{height}"
    );
    assert!(
        doc.query("[data-slot=card] [data-slot=card-title]")
            .is_some()
    );
    assert!(
        doc.query("[data-slot=progress]").is_some(),
        "a Bits UI primitive mounted"
    );

    // Events pass through the component's `{...restProps}` to the element.
    doc.click(button);
    doc.click(button);
    assert_eq!(text(&doc, "#count"), "Clicked 2");
    assert_eq!(text(&doc, "[data-slot=badge]:nth-of-type(2)"), "2 clicks");

    // `bind:value` on the Input's <input>: the value reaches the element.
    assert_eq!(
        doc.attr(doc.query("#name").unwrap(), "value").as_deref(),
        Some("Ada")
    );
    assert_eq!(text(&doc, "#greeting"), "Hello, Ada.");
}
